blk=(df['race'].str.lower()=='black').astype(int).to_numpy();
hsp=(df['race'].str.lower()=='hipanic').astype(int).to_numpy();
male=(df['sex'].str.lower()=='male').astype(int).to_numpy();
je=(df['ever_jailed']).to_numpy();
X=np.column_stack([np.ones(len(df)), blk, hsp, male, je]).astype(float)
