bounds=[(None,None)]*p+[(0,None)]*(2*n)
for m in ['highs','highs-ds','highs-ipm']:
    r=linprog(c, A_eq=Aeq, b_eq=y, bounds=bounds, method=m)
    b=r.x[:p]
    print(m, r.success, b)
